function curve(n,start,end,wiggle=.04,phase=0){return Array.from({length:n},(_,i)=>{const t=i/(n-1);return start*Math.pow(end/start,t)*(1+Math.sin(Math.PI*t)*wiggle*(.6*Math.sin(t*14*Math.PI+phase)+.7*Math.sin(t*5*Math.PI-phase)));});}
