function readHash(){const p=new URLSearchParams(location.hash.replace(/^#/,''));const page=p.get('page');if(PAGES.some(x=>x.id===page))S.page=page;S.asset=p.get('asset')||DEFAULTS[S.page];const allowed={crypto:CRYPTO.map(x=>x.id),bitcoin:['BTC'],record:['model'],commodities:COMMODITIES.map(x=>x.id),strategies:STRATEGIES.map(x=>x.id),reserves:Object.keys(RESERVES),forex:CURRENCIES.filter(x=>x.id!=='USD').map(x=>x.id),bonds:TENORS};if(!allowed[S.page].includes(S.asset))S.asset=DEFAULTS[S.page];S.tab=p.get('view')||'overview';const views={crypto:['overview','flows','leverage','market'],bitcoin:['overview','cycle','derivatives','history'],record:['overview','decisions','assumptions'],commodities:['overview','explore','relationships','compare','note'],strategies:['overview','conditions','compare'],reserves:['overview','events','compare'],forex:['overview','matrix','exposure','note'],bonds:['overview','credit','transmission']};if(!views[S.page].includes(S.tab))S.tab='overview';S.range=['1M','3M','6M'].includes(p.get('range'))?p.get('range'):'6M';S.state=['default','partial','conflict','empty','loading','error'].includes(p.get('state'))?p.get('state'):'default';S.theme=p.get('theme')==='light'?'light':'dark';S.inverted=p.get('invert')==='1';for(const [key,def,lo,hi] of [['replay',100,25,100],['brush',0,0,100],['shift',50,-100,100],['cost',8,0,30],['roll',-1.5,-5,5]]){const v=Number(p.has(key)?p.get(key):def);S[key]=Number.isFinite(v)?Math.max(lo,Math.min(hi,v)):def;}S.curveMode=p.get('curve')==='scenario'?'scenario':'observed';S.reserveBasis=p.get('basis')==='demand'?'demand':'imports';S.compare=(p.has('compare')?p.get('compare').split(','):['gold','wti','copper']).filter((v,i,a)=>COMMODITIES.some(x=>x.id===v)&&a.indexOf(v)===i).slice(0,4);S.evidence=p.get('evidence')||'';}
function saveHash(push=false){const q=new URLSearchParams({page:S.page,view:S.tab,asset:S.asset,range:S.range,state:S.state,theme:S.theme});if(S.inverted)q.set('invert','1');for(const [k,v,d]of[['replay',S.replay,100],['brush',S.brush,0],['shift',S.shift,50],['cost',S.cost,8],['roll',S.roll,-1.5]])if(v!==d)q.set(k,String(v));if(S.curveMode!=='observed')q.set('curve',S.curveMode);if(S.reserveBasis!=='imports')q.set('basis',S.reserveBasis);if(S.compare.join(',')!=='gold,wti,copper')q.set('compare',S.compare.join(','));if(S.evidence)q.set('evidence',S.evidence);const hash='#'+q.toString();if(hash!==location.hash)history[push?'pushState':'replaceState'](null,'',hash);}

const meta=()=>PAGES.find(p=>p.id===S.page);
function nav(page){S={...S,evidence:'',page,tab:'overview',asset:DEFAULTS[page],state:'default',replay:100,brush:0,inverted:false,curveMode:'observed'};saveHash(true);render();window.scrollTo(0,0);}
function pageHeader(){return `<div class="page-head"><div><h1>${meta().name}</h1><div class="page-meta"><span>${S.page==='bitcoin'&&S.replay<100?sampleDate(Math.max(25,Math.round(121*S.replay/100))-1)+' 2025':'30 Jun 2025'}</span><span class="dot"></span><span>Illustrative</span><span class="pill">${S.replay<100?'Historical view':'Research workspace'}</span></div></div><div class="head-actions"><button class="btn quiet" data-action="sources">${icon('info',true)}<span>Sources</span></button><button class="btn" data-action="share">${icon('link',true)}<span>Copy view</span></button></div></div>`;}
function tabs(items){return `<div class="task-tabs" role="tablist" aria-label="Analysis views">${items.map(([id,label])=>`<button data-tab="${id}" class="${S.tab===id?'on':''}" id="tab-${id}" role="tab" tabindex="${S.tab===id?0:-1}" aria-selected="${S.tab===id}" aria-controls="analysis-content">${label}</button>`).join('')}</div>`;}
function ranges(){return `<div class="seg" role="group" aria-label="Chart time range">${['1M','3M','6M'].map(x=>`<button class="${S.range===x?'on':''}" data-range="${x}" aria-pressed="${S.range===x}">${x}</button>`).join('')}</div>`;}
function stat(label,value,note,cls=''){return `<div class="stat"><span class="caption">${label}</span><strong class="value num ${cls}">${value}</strong>${note?`<span class="caption">${note}</span>`:''}</div>`;}
function evidenceLink(topic='sources',text='Source & method'){return `<button class="source-link" data-evidence="${topic}">${icon('info',true)}${text}</button>`;}
function panelTitle(title,sub='',right=''){return `<div class="panel-hd"><div><h2>${title}</h2>${sub?`<p class="panel-sub">${sub}</p>`:''}</div>${right}</div>`;}
function emptyState(title,reason,action='Reset view'){return `<div class="empty">${icon('empty')}<h3>${title}</h3><p>${reason}</p><button class="btn" data-action="reset">${action}</button></div>`;}
function skeleton(){return `<div class="panel panel-pad" aria-busy="true" aria-label="Loading analysis"><div class="skeleton skeleton-line" style="width:34%"></div><div class="skeleton skeleton-line" style="width:21%;height:28px"></div><div class="skeleton skeleton-chart"></div><div class="skeleton skeleton-line" style="width:65%"></div></div>`;}
const STATE_COPY={crypto:['One derivatives source is delayed. Prices and fund-flow history remain available.','Price is rising while leverage is elevated. Inspect the disagreement.'],bitcoin:['The current model allocation is unavailable. The last price record remains inspectable.','Trend is positive; derivatives evidence is weakening. Both remain visible.'],record:['The selected cost basis is incomplete. The return comparison is withheld.','The benchmark leads on return; the model has a smaller drawdown.'],commodities:['Copper inventory is from an earlier release. Price evidence remains available.','Copper is rising while warehouse inventories are building. The explanation is unresolved.'],strategies:['The gold settlement is missing. Its result is withheld; other records remain inspectable.','One thesis condition has failed. The supporting evidence has not been removed.'],reserves:['One country has an estimate, not a comparable reported stock.','The revised release differs from the first publication. Inspect both vintages.'],forex:['CHF is delayed. Other pairs retain their own source timestamps.','The rate differential and the spot trend point in different directions.'],bonds:['Credit-market functioning data is unavailable. Treasury curves are still shown.','A steeper curve has competing explanations. Inspect rates, inflation and funding separately.']};
function stateNotice(){if(!['partial','conflict'].includes(S.state))return '';return `<div class="state-notice">${icon('warning')}<span>${STATE_COPY[S.page][S.state==='partial'?0:1]}</span><button class="link-btn" data-evidence="quality" style="margin-left:auto;min-height:40px;white-space:nowrap">Inspect</button></div>`;}
function tickValue(v){return Math.abs(v)>=1000?Math.round(v).toLocaleString():v.toFixed(Math.abs(v)<.1?5:Math.abs(v)<10?2:Math.abs(v)<100?1:0);}
function chartSvg(series,{height=260,labels=['Jan','Feb','Mar','Apr','May','Jun'],unit='',min=null,max=null,area=true,markers=false,brush=false}={}){const W=window.innerWidth<640?340:820,H=height,L=15,R=62,T=18,B=31;const all=series.flatMap(x=>x.values).filter(Number.isFinite);let lo=min===null?Math.min(...all):min,hi=max===null?Math.max(...all):max;const pad=(hi-lo)*.14||1;if(min===null)lo-=pad;if(max===null)hi+=pad;const x=(i,n)=>L+i/(Math.max(1,n-1))*(W-L-R),y=v=>T+(hi-v)/(hi-lo)*(H-T-B);let out=`<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(series.map(x=>x.label).join(' compared with '))}; illustrative ${unit} history">`;for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4;out+=`<line class="gridline" x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}"/><text x="${W-R+11}" y="${y(v)+3}">${tickValue(v)}${unit==='%'?'%':''}</text>`;}if(brush){out+=`<rect x="${L+(W-L-R)*.36}" y="${T}" width="${(W-L-R)*.24}" height="${H-T-B}" fill="var(--series)" opacity=".07"/><line x1="${L+(W-L-R)*.36}" x2="${L+(W-L-R)*.36}" y1="${T}" y2="${H-B}" stroke="var(--series)" stroke-dasharray="3 4" opacity=".5"/>`;}
series.forEach((s,k)=>{const pts=s.values.map((v,i)=>`${i?'L':'M'}${x(i,s.values.length).toFixed(1)},${y(v).toFixed(1)}`).join(' ');const color=s.color||['var(--series)','var(--compare)','var(--cyan)'][k];if(k===0&&area)out+=`<defs><linearGradient id="fill-${S.page}" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${color}" stop-opacity=".13"/><stop offset="100%" stop-color="${color}" stop-opacity="0"/></linearGradient></defs><path d="${pts}L${W-R},${H-B}L${L},${H-B}Z" fill="url(#fill-${S.page})"/>`;out+=`<path d="${pts}" stroke="${color}" stroke-width="${k===0?2.3:1.6}" fill="none"${s.dashed?' stroke-dasharray="5 5"':''}/>`;const end=s.values.at(-1);out+=`<circle cx="${W-R}" cy="${y(end)}" r="3" fill="${color}"/>`;if(markers&&k===0)[.24,.56,.77].forEach((t,j)=>{const i=Math.floor((s.values.length-1)*t);out+=`<circle cx="${x(i,s.values.length)}" cy="${y(s.values[i])}" r="5" fill="var(--panel)" stroke="${color}" stroke-width="1.5"/><text x="${x(i,s.values.length)}" y="${y(s.values[i])-13}" text-anchor="middle">${j+1}</text>`;});});labels.forEach((s,i)=>{out+=`<text x="${L+i/(labels.length-1)*(W-L-R)}" y="${H-7}" text-anchor="${i===0?'start':i===labels.length-1?'end':'middle'}">${s}</text>`;});return out+'</svg>';}
function chartData(values){const n=S.range==='1M'?21:S.range==='3M'?61:values.length;return values.slice(-n);}
function sampleDate(index){return new Date(Date.UTC(2025,0,1)+Math.round(180*index/120)*86400000).toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'});}
function historyLabels(end=120,count=121){const start=Math.max(0,end-count+1);return Array.from({length:5},(_,i)=>sampleDate(Math.round(start+(end-start)*i/4)));}
function lineLabels(){return historyLabels(120,S.range==='1M'?21:S.range==='3M'?61:121);}
function priceSeries(end,monthlyReturn,wiggle=.05,phase=0,halfReturn=null){const before=end/(1+monthlyReturn/100);return curve(101,halfReturn===null?before*.88:end/(1+halfReturn/100),before,wiggle,phase).concat(curve(21,before,end,wiggle*.28,phase).slice(1));}
function rebase(values){return values.map(x=>x/values[0]*100);}
function monthlyDrawdowns(values){let peak=values[0];const dd=values.map(x=>{peak=Math.max(peak,x);return (x/peak-1)*100;});const n=Math.ceil(values.length/6);return Array.from({length:6},(_,i)=>Math.min(0,...dd.slice(i*n,(i+1)*n)));}

function spark(values,color='var(--series)'){const mn=Math.min(...values),mx=Math.max(...values);return `<svg class="spark" viewBox="0 0 90 24" aria-hidden="true"><path d="${values.map((v,i)=>`${i?'L':'M'}${i/(values.length-1)*90},${22-(v-mn)/(mx-mn||1)*20}`).join(' ')}" stroke="${color}" fill="none" stroke-width="1.5"/></svg>`;}
function driverTrack(name,state,seed=0){return `<div class="driver-track"><button class="track-label" data-evidence="driver">${name}</button><div class="track" aria-hidden="true">${Array.from({length:Math.max(10,Math.round(38*S.replay/100))},(_,i)=>`<i style="height:${9+Math.sin(i*.3+seed)*4+((i*7)%8)}px;background:${i>27&&state==='Elevated'?'var(--warn)':'var(--series)'};opacity:${.18+((i*7+seed)%11)*.055}"></i>`).join('')}</div><span class="state ${state==='Elevated'?'warn':''}">${state}</span></div>`;}
function metric(label,value,cls=''){return `<div class="metric"><small>${label}</small><strong class="num ${cls}">${value}</strong></div>`;}
function cryptoTable(){return `<div class="panel below">${panelTitle('Market board','One-month returns · select an asset',`<button class="link-btn" data-evidence="universe">Universe ${icon('chevron',true)}</button>`)}<div class="table-wrap"><table class="data-table"><thead><tr><th>Asset</th><th class="right">1M</th><th class="right mobile-hide">Relative to BTC</th><th class="mobile-hide">Price path</th><th>Market state</th><th class="mobile-hide">Leverage</th><th></th></tr></thead><tbody>${CRYPTO.map(a=>`<tr data-asset="${a.id}" tabindex="0" role="button" aria-label="Inspect ${a.name}" class="${S.asset===a.id?'selected':''}"><td><div class="asset-name"><span class="asset-logo">${a.symbol}</span><span><strong>${a.name}</strong><small>${a.id}</small></span></div></td><td class="num right ${a.ret>=0?'up':'down'}">${signed(a.ret)}%</td><td class="num right mobile-hide ${a.relative>=0?'up':'down'}">${signed(a.relative)}%</td><td class="mobile-hide">${spark(curve(20,100,100+a.ret,.06,a.ret),a.ret>=0?'var(--up)':'var(--down)')}</td><td class="secondary">${a.trend}</td><td class="mobile-hide ${a.lev==='Elevated'?'warn':'secondary'}">${S.state==='partial'&&a.id==='BTC'?'Delayed':a.lev}</td><td>${icon('chevron',true)}</td></tr>`).join('')}</tbody></table></div></div>`;}
function crypto(){const a=CRYPTO.find(x=>x.id===S.asset)||CRYPTO[0];let graph=chartSvg([{label:a.name,values:rebase(chartData(a.id==='BTC'?BENCH:priceSeries(100+a.ret,a.ret,.07,1)))},{label:'Crypto market',values:rebase(chartData(priceSeries(109.7,9.7,.043,2)))}],{labels:lineLabels(),height:280,markers:false});let chartTitle='Bitcoin versus the crypto market';if(S.tab==='flows'){chartTitle='Fund flows, without the noise';graph=barChart([120,96,-45,78,32,139],['Jan','Feb','Mar','Apr','May','Jun'],'USD millions');}if(S.tab==='leverage'&&S.state==='partial'){graph=emptyState('Leverage aggregate delayed','The affected series is withheld. Price and fund-flow history remain inspectable.','Use complete design fixture');}else if(S.tab==='leverage'){chartTitle='Price and positioning are diverging';graph=chartSvg([{label:'Open interest index',values:curve(121,100,129,.07)},{label:'Spot volume index',values:curve(121,100,114,.08,2)}],{height:280,unit:'index'});}return `${tabs([['overview','Overview'],['flows','Flows'],['leverage','Leverage'],['market','Market board']])}<div class="summary"><div><div class="label">Market read</div><h2 class="headline">Leadership is broadening.</h2><p class="hero-note">More assets are participating. Check how much is supported by spot demand.</p></div><div class="summary-side">${stat('Assets above their 50-day trend','68%','Illustrative universe')}${stat('Fund flows · 7 days','+$420m','Net subscriptions','up')}</div></div>${S.tab==='market'?cryptoTable():`<div class="split"><section class="panel">${panelTitle(chartTitle,S.tab==='overview'?`${a.name} · rebased to 100`:S.tab==='flows'?'Tracked crypto funds · net subscriptions':'Tracked derivatives · common starting value',S.tab==='overview'?ranges():'<span class="tag">Jan–Jun</span>')}${S.tab==='overview'?`<div class="quote"><span class="big num">$${money(a.price)}</span><span class="move num ${a.ret>=0?'up':'down'}">${signed(a.ret)}% <span class="muted">1M</span></span><span class="spacer"></span><button class="link-btn" data-evidence="asset">${a.id} ${icon('external',true)}</button></div>`:''}<div class="chart-shell">${graph}</div><div class="panel-bottom"><div class="legend"><span><i class="legend-line"></i>${S.tab==='leverage'?'Open interest':S.tab==='flows'?'Net subscriptions':a.name}</span>${S.tab==='flows'||S.state==='partial'&&S.tab==='leverage'?'':`<span><i class="legend-line compare"></i>${S.tab==='leverage'?'Spot volume':'Crypto market'}</span>`}</div>${evidenceLink('chart')}</div></section><aside class="panel panel-pad"><div><div class="row between"><h2>Under the move</h2>${icon('market',true)}</div><div class="evidence-row"><div class="top"><span>Participation</span><span class="up">Broadening</span></div><p class="reason">Strength is extending beyond Bitcoin.</p><button class="link-btn" data-evidence="breadth">See the breadth ${icon('arrow',true)}</button></div><div class="evidence-row"><div class="top"><span>Spot demand</span><span class="up">Supporting</span></div><p class="reason">Fund subscriptions remain positive over the selected week.</p><button class="link-btn" data-tab="flows">Inspect flows ${icon('arrow',true)}</button></div><div class="evidence-row"><div class="top"><span>Derivatives</span><span class="warn">${S.state==='partial'?'Delayed source':'More crowded'}</span></div><p class="reason">${S.state==='partial'?'The aggregate is withheld until its source is current.':'Funding and open interest have risen together.'}</p><button class="link-btn" data-tab="leverage">Inspect leverage ${icon('arrow',true)}</button></div></div></aside></div>${cryptoTable()}`}`;}
function bitcoin(){const replayed=S.replay<100;const vals=BENCH.map(v=>v/141.1*104820).slice(0,Math.max(25,Math.round(121*S.replay/100)));const localReturn=(vals.at(-1)/vals[Math.max(0,vals.length-21)]-1)*100;const snap=DECISIONS.filter(d=>d.index<=vals.length-1).at(-1);return `${tabs([['overview','Overview'],['cycle','Cycle'],['derivatives','Derivatives'],['history','History']])}<div class="summary"><div><div class="label">${replayed?'As-known-then review':'Bitcoin read'}</div><h2 class="headline">${replayed?'Historical evidence, preserved.':'Trend holds. Leverage disagrees.'}</h2><p class="hero-note">Follow the price trend; keep the contradiction in view.</p></div><button class="btn" data-go="record">${icon('record',true)}Track record</button></div><div class="split"><section class="panel">${panelTitle(S.tab==='cycle'?'Price through the cycle':S.tab==='derivatives'?'Price against leverage':'One price. Different drivers.',replayed?'Historical fixture · original vintage required in production':'BTC / USD · qualified history',ranges())}<div class="quote"><strong class="big num">$${money(vals.at(-1))}</strong><span class="move num ${localReturn>=0?'up':'down'}">${signed(localReturn)}% <span class="muted">1M</span></span></div><div class="chart-shell">${chartSvg([{label:'Bitcoin price',values:chartData(vals)}],{height:280,labels:historyLabels(vals.length-1,chartData(vals).length),markers:false})}</div>${driverTrack('Price trend',snap.trend,0)}${driverTrack('Spot demand',snap.spot,1)}${driverTrack('Leverage',snap.leverage,2)}<div class="window-controls">${icon('history',true)}<span class="nowrap">Review history</span><input aria-label="Replay historical record" type="range" min="25" max="100" value="${S.replay}" data-slider="replay"><button class="link-btn nowrap" data-action="latest">${replayed?'Return to latest':'Latest record'}</button></div></section><aside><section class="panel panel-pad"><div class="row between"><h2>Model allocation</h2>${evidenceLink('model','Explain')}</div>${S.state==='partial'?`<div class="empty" style="min-height:150px;padding:15px 0"><h3>Unavailable</h3><p>The current decision record could not be qualified.</p></div>`:`<div class="model-allocation"><strong class="num">${snap.after}<span style="font-size:24px">%</span></strong><span class="secondary small">Bitcoin</span></div><div class="allocation-bar"><span class="invested" style="width:${snap.after}%"></span><span class="cash" style="width:${100-snap.after}%"></span></div><div class="row between small"><span class="secondary">Model capital</span><span class="muted num">${100-snap.after}% cash</span></div>`}<div class="divider"></div><p class="small secondary">Model target, separate from your holdings.</p><button class="link-btn" data-go="record">Trace the decisions ${icon('arrow',true)}</button></section><section class="panel panel-pad below"><h2>What changes the read</h2><div class="condition">${icon('market')}<div>Spot demand fades<p>Review when the qualified demand observation weakens.</p></div></div><div class="condition">${icon('warning')}<div>Leverage keeps building<p>Inspect whether new positioning is outrunning participation.</p></div></div><button class="link-btn" data-evidence="conditions">Inspect conditions ${icon('arrow',true)}</button></section></aside></div>${S.tab==='history'?decisionLedger(0,vals.length-1):`<div class="panel below"><div class="panel-bottom" style="border-top:0"><div class="row"><span class="tag">${replayed?sampleDate(vals.length-1)+' · historical fixture':'Latest interpretation'}</span><span class="small secondary">Inspect the original inputs before comparing another period.</span></div><button class="link-btn" data-evidence="replay">${icon('book',true)}Evidence record</button></div></div>`}`;}
function maxDD(v){let peak=v[0],m=0;v.forEach(x=>{peak=Math.max(peak,x);m=Math.min(m,x/peak-1)});return m*100;}
const DECISIONS=[
{id:'D-2025-01-01',index:0,date:'1 Jan 2025',title:'Initial model record',reason:'Initial qualified synthetic observation',before:0,after:20,trend:'Developing',spot:'Mixed',leverage:'Neutral'},
{id:'D-2025-04-28',index:78,date:'28 Apr 2025',title:'Exposure restored',reason:'Recovery condition qualified',before:20,after:35,trend:'Recovering',spot:'Improving',leverage:'Neutral'},
{id:'D-2025-05-21',index:93,date:'21 May 2025',title:'Exposure increased',reason:'Trend and spot demand aligned',before:35,after:60,trend:'Rising',spot:'Supporting',leverage:'Moderate'},
{id:'D-2025-06-12',index:108,date:'12 Jun 2025',title:'Exposure reduced',reason:'Leverage condition weakened',before:60,after:45,trend:'Rising',spot:'Supporting',leverage:'Elevated'}];
function decisionLedger(start=0,end=120){const rows=DECISIONS.filter(d=>d.index>=start&&d.index<=end&&d.index>0).slice().reverse();return `<section class="panel below">${panelTitle('Decision ledger',`${sampleDate(start)}–${sampleDate(end)} · model changes only`,evidenceLink('history','Method'))}${rows.length?rows.map(d=>`<button class="decision-row" style="width:100%;text-align:left" data-evidence="decision:${d.id}"><span class="date-tag">${d.date.replace(' 2025','')}</span><span><span class="decision-name">${d.title}</span><p>${d.reason}</p></span><span class="num right">${d.after}%</span>${icon('chevron',true)}</button>`).join(''):'<div class="panel-pad"><h3>No model changes in this window.</h3><p class="small secondary" style="margin-top:10px">The allocation held between recorded decisions.</p></div>'}</section>`;}

function record(){if(S.state==='partial')return `${tabs([['overview','Performance'],['decisions','Decision ledger'],['assumptions','Assumptions']])}<section class="panel">${emptyState('Return comparison unavailable','The selected cost basis is incomplete. Original decision records remain inspectable.','Use complete design fixture')}</section>${decisionLedger()}`;const baseStart=S.range==='1M'?100:S.range==='3M'?60:0;const start=baseStart+Math.round(S.brush/100*(100-baseStart)),m=MODEL.slice(start),b=BENCH.slice(start);const mr=(m.at(-1)/m[0]-1)*100,br=(b.at(-1)/b[0]-1)*100;return `${tabs([['overview','Performance'],['decisions','Decision ledger'],['assumptions','Assumptions']])}<div class="summary"><div><div class="row"><span class="label">Model record</span><span class="pill">Simulated</span></div><h2 class="headline">${mr<br?'Smoother, with lower return.':'The selected window differs.'}</h2><p class="hero-note">Compare the result and the drawdown over the same dates.</p></div><button class="btn" data-go="bitcoin">${icon('bitcoin',true)}Bitcoin Vector</button></div><div class="stat-band">${stat('Model return · net',signed(mr)+'%','Selected window',mr>=0?'up':'down')}${stat('Worst drawdown',signed(maxDD(m))+'%','Peak to trough','down')}${stat('Versus Bitcoin',signed(mr-br)+' pp','Matched dates',mr>=br?'up':'down')}${stat('Benchmark return',signed(br)+'%','Matched dates',br>=0?'up':'down')}</div>${S.tab==='decisions'?decisionLedger(start,120):S.tab==='assumptions'?`<div class="split"><section class="panel panel-pad"><h2>A comparison you can reconstruct</h2><div class="evidence-kv"><span>Record type</span><b>Simulated model record</b></div><div class="evidence-kv"><span>Return convention</span><b>Net total return · USD</b></div><div class="evidence-kv"><span>Benchmark</span><b>BTC buy-and-hold · matching dates</b></div><div class="evidence-kv"><span>Parameter revisions</span><b>New experiment; original preserved</b></div><div class="evidence-kv"><span>Costs</span><b>Inspect record-specific model</b></div><button class="link-btn" data-evidence="costs">Cost and slippage assumptions ${icon('arrow',true)}</button></section><aside class="panel panel-pad"><div><h2>Evidence, not a promise</h2><p class="small secondary" style="margin-top:14px">A historical result belongs to one version and one sample. The live record, simulated record and backtest never share a headline.</p><button class="link-btn" data-evidence="experiments">Experiment history ${icon('arrow',true)}</button></div></aside></div>`:`<div class="split"><section class="panel">${panelTitle('Growth of 100','USD · matching start date · net model return',ranges())}<div class="chart-shell">${chartSvg([{label:'Model',values:m.map(x=>x/m[0]*100)},{label:'Bitcoin',values:b.map(x=>x/b[0]*100)}],{height:285,labels:historyLabels(120,m.length)})}</div><div class="panel-bottom"><div class="legend"><span><i class="legend-line"></i>Model</span><span><i class="legend-line compare"></i>Bitcoin</span></div>${evidenceLink('returns')}</div><div class="chart-shell drawdown">${barChart(monthlyDrawdowns(m),Array.from({length:6},(_,i)=>sampleDate(Math.min(120,start+Math.round((120-start)*i/5)))),'drawdown %',95)}</div><div class="window-controls"><span class="nowrap small secondary">Inspect a period</span><input type="range" min="0" max="100" value="${S.brush}" data-slider="brush" aria-label="Change selected performance window"><button class="link-btn" data-action="clear-brush">Full record</button></div></section><aside class="panel panel-pad"><div><h2>${S.brush?'Selected period':'Read the trade-off'}</h2><div class="evidence-row"><div class="top"><span>Return</span><span class="num ${mr>=br?'up':'down'}">${signed(mr-br)} pp</span></div><p class="reason">${mr>=br?'The model finished higher over the same window.':'Bitcoin finished higher over the same window.'}</p></div><div class="evidence-row"><div class="top"><span>Drawdown</span><span class="num">${Math.abs(maxDD(m)).toFixed(1)}%</span></div><p class="reason">Compare the deepest peak-to-trough decline within these dates.</p></div><div class="evidence-row"><div class="top"><span>Evidence</span><span class="tag">Versioned</span></div><p class="reason">Every change opens its original decision and available inputs.</p><button class="link-btn" data-tab="decisions">Inspect decisions ${icon('arrow',true)}</button></div><button class="link-btn" data-tab="assumptions">Costs & assumptions ${icon('arrow',true)}</button></div></aside></div>${decisionLedger(start,120)}`}`;}
function barChart(values,labels,unit,height=250){const W=window.innerWidth<640?340:820,H=height,L=22,R=30,T=20,B=30;const min=Math.min(0,...values)*1.2,max=Math.max(0,...values)*1.2;const span=max-min||1,y=v=>T+(max-v)/span*(H-T-B),cw=(W-L-R)/values.length;let s=`<svg class="chart" style="min-height:${height<100?'60px':'auto'}" viewBox="0 0 ${W} ${H}" role="img" aria-label="Illustrative ${esc(unit)}"><line x1="${L}" x2="${W-R}" y1="${y(0)}" y2="${y(0)}" stroke="var(--line-3)"/>`;values.forEach((v,i)=>{const bh=Math.abs(y(v)-y(0));s+=`<rect x="${L+i*cw+cw*.25}" y="${Math.min(y(0),y(v))}" width="${cw*.5}" height="${Math.max(.6,bh)}" rx="2" fill="${v>=0?'var(--up)':'var(--down)'}" opacity=".65"/><text x="${L+i*cw+cw*.5}" y="${H-8}" text-anchor="middle">${labels[i]}</text>${height>100?`<text x="${L+i*cw+cw*.5}" y="${v>=0?y(v)-7:y(v)+14}" text-anchor="middle">${signed(v,Math.abs(v)<20?1:0)}</text>`:''}`;});s+=`<text x="${L}" y="12">${unit}</text></svg>`;return s;}
function assetPills(){return `<div class="asset-pills">${['gold','wti','copper','silver'].map(id=>`<button data-asset="${id}" class="${S.asset===id?'on':''}">${COMMODITIES.find(x=>x.id===id).name}</button>`).join('')}<button data-action="all-commodities">All 17 ${icon('chevron',true)}</button></div>`;}
function commodityMap(){const families=[...new Set(COMMODITIES.map(x=>x.fam))];return `<section class="panel">${panelTitle('Across the complex','One month · a common return scale',`<span class="tag">17 markets</span>`)}<div class="family-map">${families.map(f=>`<div class="family"><h3>${f}</h3>${COMMODITIES.filter(x=>x.fam===f).map(a=>`<button class="map-asset ${S.asset===a.id?'on':''}" data-asset="${a.id}" aria-label="Inspect ${a.name}, ${signed(a.ret)} percent"><div class="map-top"><strong>${a.name}</strong><span class="num ${a.ret>=0?'up':'down'}">${signed(a.ret)}%</span></div><div class="bar-axis" aria-hidden="true"><i class="${a.ret<0?'negative':''}" style="left:${a.ret>=0?50:50-Math.abs(a.ret)/12.6*48}%;width:${Math.abs(a.ret)/12.6*48}%"></i></div></button>`).join('')}</div>`).join('')}</div><div class="map-unit">Returns share one zero and one scale. Each market retains its own price unit.</div></section>`;}
function commoditySide(a){return `<aside class="panel panel-pad"><div><div class="row between"><span class="label">Selected market</span>${icon('commodity',true)}</div><h2 style="font-size:24px;margin:12px 0 2px">${a.name}</h2><div class="row" style="align-items:baseline"><span class="soft-number num">${money(a.price)}</span><span class="small muted">${a.unit}</span></div><div class="num ${a.ret>=0?'up':'down'}" style="margin-top:5px;font-size:12px">${signed(a.ret)}% <span class="muted">1M</span></div><div style="margin:18px 0">${spark(curve(40,100,100+a.ret,.06,2),a.ret>=0?'var(--up)':'var(--down)')}</div><div class="evidence-row"><div class="top"><span>Price trend</span><strong class="secondary">${a.trend}</strong></div><p class="reason">${a.id==='copper'?'Price strength is visible. Physical confirmation needs its own evidence.':'Separate the price move from its proposed explanation.'}</p></div><div class="evidence-row"><div class="top"><span>Physical context</span><span class="${S.state==='partial'?'warn':'secondary'}">${S.state==='partial'?'Earlier release':'Inspect'}</span></div><p class="reason">Inventories, supply and demand keep their own release dates.</p></div><button class="btn primary" data-tab="explore" style="width:100%;margin-top:16px">Explore ${a.name} ${icon('arrow',true)}</button></div></aside>`;}
function compareCommodities(){return `<section class="panel">${panelTitle('Compare like with like','One-month returns · up to four markets',evidenceLink('comparison'))}<div class="panel-pad"><div class="compare-list">${['gold','wti','copper','silver','gas','wheat'].map(id=>`<button data-compare="${id}" class="${S.compare.includes(id)?'on':''}" aria-pressed="${S.compare.includes(id)}">${S.compare.includes(id)?'✓ ':''}${COMMODITIES.find(x=>x.id===id).name}</button>`).join('')}</div></div>${S.compare.length?`<div class="compare-bars">${S.compare.map(id=>{const a=COMMODITIES.find(x=>x.id===id);return `<div class="compare-bar-row"><span>${a.name}</span><div class="bar-axis"><i class="${a.ret<0?'negative':''}" style="left:${a.ret>=0?50:50-Math.abs(a.ret)/12.6*48}%;width:${Math.abs(a.ret)/12.6*48}%"></i></div><span class="num right ${a.ret>=0?'up':'down'}">${signed(a.ret)}%</span></div>`;}).join('')}</div>`:'<div class="empty"><h3>Choose a market to compare</h3><p>Select a market above, or restore the starter comparison.</p><button class="btn" data-action="restore-compare">Restore comparison</button></div>'}<div class="panel-bottom"><span class="small muted">Publisher month is distinct from a 20-session lookback.</span>${evidenceLink('windows')}</div></section>`;}
let DRAFTS={};try{DRAFTS=JSON.parse(localStorage.getItem('oa-design-drafts-v1')||'{}');}catch{}
function draftKey(){return S.page+':'+S.asset;}
function currentDraft(){const a=COMMODITIES.find(x=>x.id===S.asset);return DRAFTS[draftKey()]||{thesis:S.page==='forex'?`A change in the matched rate differential may help explain ${S.asset}/USD.`:`${a?.name||'This market'} may be responding to a change in its physical balance.`,metric:S.page==='forex'?'Matched two-year rate differential':'Price',unit:S.page==='forex'?'bp':a?.unit||'',source:'illustrative/'+S.page+'/'+S.asset,threshold:'',operator:'lt',note:''};}
function rememberDraft(){const f=document.getElementById('research-form');if(!f||!f.dataset.context)return;const d={};for(const k of ['thesis','metric','unit','source','threshold','operator','note']){const el=f.querySelector('#'+k);d[k]=el?el.value:'';}DRAFTS[f.dataset.context]=d;try{localStorage.setItem('oa-design-drafts-v1',JSON.stringify(DRAFTS));}catch{}}
function researchForm(){const d=currentDraft();return `<section class="panel"><div class="research-note"><div class="row between"><span class="label">Research note</span><span class="tag">Local draft</span></div><h2 style="font-size:25px;margin:10px 0 22px">Keep the question precise.</h2><form id="research-form" data-context="${draftKey()}"><div class="field"><label for="thesis">Explanation to test</label><textarea id="thesis" required>${esc(d.thesis)}</textarea></div><div class="field"><label for="metric">Observable condition</label><input id="metric" required value="${esc(d.metric)}"></div><div class="split equal"><div class="field"><label for="threshold">Threshold</label><input id="threshold" type="number" step="any" required placeholder="Enter a threshold" value="${esc(d.threshold)}"></div><div class="field"><label for="unit">Unit</label><input id="unit" required value="${esc(d.unit)}"></div></div><div class="field"><label for="operator">Comparison</label><select id="operator"><option value="lt" ${d.operator==='lt'?'selected':''}>Falls below</option><option value="gt" ${d.operator==='gt'?'selected':''}>Rises above</option></select></div><div class="field"><label for="source">Observation source</label><input id="source" required value="${esc(d.source)}"></div><div class="field"><label for="note">What would disprove it?</label><textarea id="note" required placeholder="A competing observation or explanation…">${esc(d.note)}</textarea></div><p class="small secondary" style="margin-bottom:16px">Saved in this browser. Export creates an inactive note; monitoring stays off.</p><button type="submit" class="btn primary">${icon('download',true)}Export draft</button></form></div></section>`;}

function commodities(){const a=COMMODITIES.find(x=>x.id===S.asset)||COMMODITIES[6];let content='';if(S.tab==='overview')content=`<div class="split">${commodityMap()}${commoditySide(a)}</div>`;else if(S.tab==='compare')content=compareCommodities();else if(S.tab==='note')content=researchForm();else if(S.tab==='relationships')content=`<section class="panel">${panelTitle('An explanation to test','Observation → mechanism → exposure',evidenceLink('relationships'))}<div class="relationship"><div class="relationship-node"><span class="step">01 · OBSERVATION</span><h3>${a.name} is ${a.ret>=0?'rising':'falling'}.</h3><p>The selected price observation is ${signed(a.ret)}% over one month.</p></div><span class="relationship-arrow">→</span><div class="relationship-node"><span class="step">02 · HYPOTHESIS</span><h3>Physical balance</h3><p>Check whether inventories and production support a tighter balance.</p><button class="link-btn" data-evidence="physical">Inspect evidence</button></div><span class="relationship-arrow">→</span><div class="relationship-node"><span class="step">03 · CONTINUATION</span><h3>Company exposure</h3><p>Inspect producers and consumers with verified economic exposure.</p><button class="link-btn" data-evidence="company">View exposure</button></div></div><div class="panel-bottom"><span class="small secondary">A mechanism remains a hypothesis until its evidence qualifies.</span><button class="link-btn" data-tab="note">Keep a research note ${icon('arrow',true)}</button></div></section>`;else content=`${assetPills()}<div class="split"><section class="panel">${panelTitle(`${a.name}: price evidence`,'Continuous contract · roll convention in sources',ranges())}<div class="quote"><span class="big num">${money(a.price)}</span><span class="unit">${a.unit}</span><span class="move num ${a.ret>=0?'up':'down'}">${signed(a.ret)}% 1M</span></div><div class="chart-shell">${chartSvg([{label:a.name,values:chartData(priceSeries(a.price,a.ret,.09,2))}],{height:295,labels:lineLabels()})}</div><div class="panel-bottom">${evidenceLink('roll','Contract & roll method')}<button class="link-btn" data-tab="relationships">Test an explanation ${icon('arrow',true)}</button></div></section>${commoditySide(a)}</div>`;return `${tabs([['overview','Overview'],['explore','Explore'],['relationships','Relationships'],['compare','Compare'],['note','Research note']])}<div class="summary"><div><div class="label">Complex read</div><h2 class="headline">Metals lead. Energy splits.</h2><p class="hero-note">Compare the moves, then examine the physical evidence.</p></div><div class="summary-side">${stat('Markets higher · 1M','11 of 17','Same observation window')}</div></div><div>${content}</div>`;}
const STRATEGIES=[{id:'gold',asset:'Gold',name:'Trend swap',state:'Conditions aligned',ret:14.8,dd:-7.2,vol:.055},{id:'wti',asset:'WTI crude',name:'Multifactor',state:'Mixed evidence',ret:6.2,dd:-12.4,vol:.095},{id:'copper',asset:'Copper',name:'Trend swap',state:'Review conditions',ret:11.3,dd:-9.1,vol:.07}];
function strategies(){if(S.state==='partial'&&S.asset==='gold')return `${tabs([['overview','Workspace'],['conditions','Conditions'],['compare','Compare models']])}<div class="summary"><div><div class="label">Conditional research</div><h2 class="headline">One settlement is missing.</h2><p class="hero-note">Inspect another record while the gold evaluation is unavailable.</p></div></div><div class="asset-pills"><button data-asset="wti">WTI crude</button><button data-asset="copper">Copper</button></div><section class="panel">${emptyState('Gold result unavailable','The missing settlement cannot be replaced with a zero return.','Use complete design fixture')}</section>`;const a=STRATEGIES.find(x=>x.id===S.asset)||STRATEGIES[0];const hypothetical=a.ret-S.cost/100*12+S.roll;return `${tabs([['overview','Workspace'],['conditions','Conditions'],['compare','Compare models']])}<div class="summary"><div><div class="label">Conditional research</div><h2 class="headline">Test the thesis.</h2><p class="hero-note">See what supports it, what would break it, and what the record shows.</p></div><button class="btn" data-go="commodities">${icon('commodity',true)}Market context</button></div><div class="strategies-layout"><aside class="panel strategy-list">${STRATEGIES.map(x=>`<button data-asset="${x.id}" class="${a.id===x.id?'on':''}" aria-pressed="${a.id===x.id}"><span class="label">${x.asset}</span><strong>${x.name}</strong><p>${x.state}</p><div class="row between" style="margin-top:15px"><span class="tag">Backtest</span><span class="num ${x.ret>=0?'up':'down'}">${signed(x.ret)}%</span></div></button>`).join('')}</aside><div>${S.tab==='compare'?`<section class="panel">${panelTitle('Results and costs together','Illustrative model evaluations · matched sample')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Model</th><th>Return</th><th>Max drawdown</th><th>Evidence</th></tr></thead><tbody>${STRATEGIES.map(x=>`<tr><td><strong>${x.asset}</strong><p class="small muted">${x.name}</p></td><td class="num up">${signed(x.ret)}%</td><td class="num down">${signed(maxDD(curve(100,100,100+x.ret,x.vol,1)))}%</td><td><button class="link-btn" data-evidence="strategy">Inspect</button></td></tr>`).join('')}</tbody></table></div><div class="panel-bottom"><span class="small secondary">Results are model-specific; underlying instruments and roll conventions matter.</span>${evidenceLink('costs')}</div></section>`:`<div class="split strategy-analysis"><section class="panel">${panelTitle(`${a.asset} · ${a.name}`,S.tab==='conditions'?'Conditions and their evidence':'Backtested model · not an account return',evidenceLink('strategy'))}${S.tab==='conditions'?`<div class="panel-pad">${conditionRows()}</div>`:`<div class="micro-metrics">${metric('Illustrative return',signed(a.ret)+'%','up')}${metric('Worst drawdown',signed(maxDD(curve(100,100,100+a.ret,a.vol,1)))+'%','down')}${metric('Record','Backtest')}</div><div class="chart-shell">${chartSvg([{label:a.name,values:curve(100,100,100+a.ret,a.vol,1)},{label:'Underlying',values:curve(100,100,119.4,.13,2)}],{height:255,markers:false})}</div><div class="panel-bottom"><div class="legend"><span><i class="legend-line"></i>Model</span><span><i class="legend-line compare"></i>Underlying</span></div><button class="link-btn" data-evidence="experiment">View evaluation ${icon('external',true)}</button></div>`}<div class="scenario-header">Hypothetical sensitivity · separate from the record</div><div class="scenario-fields"><div class="scenario-field"><label>Cost per rebalance <span class="num">${S.cost} bp</span></label><input type="range" min="0" max="30" value="${S.cost}" data-slider="cost" aria-label="Hypothetical cost per rebalance"></div><div class="scenario-field"><label>Roll contribution <span class="num">${signed(S.roll)} pp</span></label><input type="range" min="-5" max="5" step=".25" value="${S.roll}" data-slider="roll" aria-label="Hypothetical roll contribution"></div><div class="scenario-result"><div><span class="small secondary">Illustrative net sensitivity</span><p class="small muted">12 rebalances · fixed base return</p></div><strong class="num ${hypothetical>=0?'up':'down'}" id="strategy-sensitivity">${signed(hypothetical)}%</strong></div><button class="link-btn" data-evidence="sensitivity">Inspect the assumptions</button></div></section><aside class="panel panel-pad"><div><h2>Thesis conditions</h2>${conditionRows()}<div class="divider"></div><button class="link-btn" data-tab="conditions">Inspect every condition ${icon('arrow',true)}</button></div></aside></div>`}</div></div>`;}
function conditionRows(){return `<div class="condition">${icon('check')}<div>Trend remains constructive<p>Inspect the trend and its invalidation level.</p></div></div><div class="condition">${icon(S.state==='conflict'?'cross':'check')}<div>${S.state==='conflict'?'Physical support weakened':'Physical evidence supports the thesis'}<p>${S.state==='conflict'?'Review the failed observation before continuing the thesis.':'Open the underlying physical observation.'}</p></div></div><div class="condition">${icon('clock')}<div>Costs stay within the test<p>Reassess if implementation assumptions change.</p></div></div><div class="condition">${icon('warning')}<div>Invalidation is explicit<p>A failed condition opens its evidence and the original evaluation.</p></div></div>`;}
function reserveEventData(country=S.asset){return (country==='JP'?[['27 Jun','Reported stock reduced','Prior 299.6m → latest 298.2m','−1.4m','Reported'],['20 Jun','Release plan announced','Planned amount; excluded from actual stocks','2.0m','Announced']]:country==='CN'?[['27 Jun','Estimate revised','Prior estimate 485m → revised 490m','+5.0m','Estimate'],['20 Jun','Coverage methodology updated','Scope uncertainty remains visible','—','Method']]:[['27 Jun','Stock estimate revised','Previous 401.8m → revised 402.4m','+0.6m','Revision'],['20 Jun','Refill delivered','Recorded addition to strategic stocks','+3.2m','Delivered'],['06 Jun','Purchase announced','Announcement; excluded from actual stock','5.0m','Announced']]);}
function reserveEvents(){return `<section class="panel below">${panelTitle('Release & refill ledger','Announcements and actual stock changes are distinct',evidenceLink('revisions'))}${reserveEventData().map((x,i)=>`<button class="event-row" style="width:100%;text-align:left" data-evidence="reserve-event:${S.asset}:${i}"><span class="date-tag">${x[0]}</span><span><strong style="font-weight:550">${x[1]}</strong><p>${x[2]}</p></span><span class="right"><span class="num">${x[3]}</span><p class="event-kind">${x[4]}</p></span>${icon('chevron',true)}</button>`).join('')}</section>`;}
function reserves(){const a=RESERVES[S.asset]||RESERVES.US,cover=a.stock/(S.reserveBasis==='imports'?a.denominator:a.demand);return `${tabs([['overview','Stock history'],['events','Release ledger'],['compare','Country context']])}<div class="summary"><div><div class="label">Reserve buffer</div><h2 class="headline">${S.asset==='US'?'A rebuilding buffer.':S.asset==='JP'?'A smaller reported buffer.':'An estimate, with visible limits.'}</h2><p class="hero-note">Separate what is in storage from what has only been announced.</p></div><div class="asset-pills">${Object.entries(RESERVES).map(([id,x])=>`<button data-asset="${id}" class="${S.asset===id?'on':''}">${x.name}</button>`).join('')}</div></div>${S.tab==='events'?reserveEvents():S.tab==='compare'?`<section class="panel">${panelTitle('Country context','Different reserve definitions · no like-for-like ranking',evidenceLink('reserve-scope'))}<div class="table-wrap"><table class="data-table"><thead><tr><th>Country</th><th>Defined stock</th><th class="right">Million barrels</th><th>Evidence</th><th></th></tr></thead><tbody>${Object.entries(RESERVES).map(([id,x])=>`<tr><td>${x.name}</td><td>${x.scope}</td><td class="num right">${x.stock.toFixed(1)}</td><td>${x.quality}</td><td><button class="link-btn" data-asset="${id}" data-tab="overview">Inspect</button></td></tr>`).join('')}</tbody></table></div></section>`:`<div class="split"><section class="panel">${panelTitle(a.name,a.scope,`<span class="pill">${a.quality}</span>`)}<div class="panel-pad" style="padding-bottom:0"><div class="row between"><div><span class="label">${a.capacity?'Stock / authorized capacity':'Stock · capacity not established'}</span></div><span class="small num ${a.change>=0?'up':'down'}">${signed(a.change)}m <span class="muted">latest change</span></span></div>${a.capacity?`<div class="reserve-tank"><div class="reserve-fill" style="width:${a.stock/a.capacity*100}%"></div><div class="reserve-ticks">${'<i></i>'.repeat(9)}</div><div class="reserve-text num">${a.stock.toFixed(1)}<small>million barrels</small></div></div><div class="row between reserve-capacity"><span class="num">${(a.stock/a.capacity*100).toFixed(1)}% of authorized capacity</span><span class="num">${a.capacity}m barrels</span></div>`:`<div style="padding:23px 0"><span class="readout-number num">${a.stock.toFixed(1)}</span> <span class="muted small">million barrels</span><p class="small muted">A fill percentage is unavailable without a comparable capacity.</p></div>`}</div><div class="chart-shell">${chartSvg([{label:`${a.name} stock`,values:curve(80,a.begin,a.stock,.02,1)}],{height:245,unit:'million barrels'})}</div><div class="panel-bottom"><div class="legend"><span><i class="legend-line"></i>Recorded stock</span></div>${evidenceLink('reserve-scope','Definition & vintage')}</div></section><aside class="panel panel-pad"><div><h2>Coverage depends on the question.</h2><div class="seg" style="margin-top:20px"><button class="${S.reserveBasis==='imports'?'on':''}" data-reserve-basis="imports">Net imports</button><button class="${S.reserveBasis==='demand'?'on':''}" data-reserve-basis="demand">Consumption</button></div><div style="padding:22px 0 18px"><span class="readout-number num">${cover.toFixed(0)}</span> <span class="secondary">days</span><p class="small muted" style="margin-top:7px">Stock divided by ${(S.reserveBasis==='imports'?a.denominator:a.demand).toFixed(1)}m barrels per day.</p></div><div class="divider"></div><p class="small secondary">This is arithmetic coverage. Deliverability, composition and usable volume are separate questions.</p><button class="link-btn" data-evidence="coverage">Inspect the denominator ${icon('arrow',true)}</button><div class="divider"></div><h3>Next check</h3><p class="small secondary" style="margin-top:8px">Read the latest published stock change before comparing a policy announcement.</p><button class="link-btn" data-tab="events">Open release ledger ${icon('arrow',true)}</button></div></aside></div>${reserveEvents()}`}`;}
function pairReturn(base,quote){const b=CURRENCIES.find(x=>x.id===base)?.ret||0,q=CURRENCIES.find(x=>x.id===quote)?.ret||0;return ((1+b/100)/(1+q/100)-1)*100;}
function currencyStrength(){return `<section class="panel strength-panel">${panelTitle('Against the dollar','One month · spot return',evidenceLink('fx-basis','Basis'))}<div class="strength-list">${CURRENCIES.filter(x=>x.id!=='USD').map(c=>`<div class="strength-row"><button data-asset="${c.id}" class="${S.asset===c.id?'blue':''}">${c.id}</button><span class="strength-track"><i style="width:${S.state==='partial'&&c.id==='CHF'?0:Math.abs(c.ret)/2.4*100}%;background:${c.ret>=0?'var(--up)':'var(--down)'};opacity:.65"></i></span><span class="num right ${c.ret>=0?'up':'down'}">${S.state==='partial'&&c.id==='CHF'?'Delayed':signed(c.ret)+'%'}</span></div>`).join('')}</div></section>`;}
function fxMatrix(){const cs=CURRENCIES;return `<section class="panel">${panelTitle('A currency is always relative','Base currency in rows · quote currency in columns',evidenceLink('fx-matrix'))}<div class="matrix"><table aria-label="One-month cross-currency return matrix"><thead><tr><th>Base / Quote</th>${cs.map(c=>`<th>${c.id}</th>`).join('')}</tr></thead><tbody>${cs.map(b=>`<tr><th>${b.id}</th>${cs.map(q=>{const v=pairReturn(b.id,q.id),delayed=S.state==='partial'&&(b.id==='CHF'||q.id==='CHF');return `<td>${b.id===q.id?'<span class="diagonal">·</span>':`<button ${delayed?'data-evidence="fx-gap"':`data-pair="${b.id}/${q.id}"`} class="${b.id===S.asset&&q.id==='USD'?'on':''}" style="background:color-mix(in srgb,${delayed?'var(--muted)':v>=0?'var(--up)':'var(--down)'} ${delayed?5:Math.min(22,5+Math.abs(v)*3)}%,var(--panel));color:${delayed?'var(--muted)':v>=0?'var(--up)':'var(--down)'}" aria-label="${q.id} per one ${b.id}; return ${delayed?'delayed':signed(v,2)+' percent'}">${delayed?'Delayed':signed(v,1)+'%'}</button>`}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div><div class="panel-bottom"><span class="small secondary">Select a pair to inspect its exact quote and return convention.</span><button class="link-btn" data-tab="overview">Pair workspace ${icon('arrow',true)}</button></div></section>`;}
function forex(){if(S.state==='partial'&&S.asset==='CHF'&&S.tab==='overview')return `${tabs([['overview','Pair workspace'],['matrix','Cross-currency'],['exposure','Carry & exposure'],['note','Research note']])}<div class="pair-main">${currencyStrength()}<section class="panel">${emptyState('CHF observation delayed','Select another currency. Other pairs retain their own qualified observations.','Use complete design fixture')}</section></div>`;const base=S.inverted?'USD':S.asset,quote=S.inverted?S.asset:'USD';const rawSpot={EUR:1.174,JPY:1/144.6,GBP:1.373,CHF:1/0.797,CAD:1/1.365,AUD:.655,NZD:.606,USD:1}[S.asset]||1.174;const spot=S.inverted?1/rawSpot:rawSpot,r=pairReturn(base,quote);return `${tabs([['overview','Pair workspace'],['matrix','Cross-currency'],['exposure','Carry & exposure'],['note','Research note']])}<div class="summary"><div><div class="label">Currency read</div><h2 class="headline">Dollar weakens. Drivers differ.</h2><p class="hero-note">Separate the common dollar move from the pair’s own drivers.</p></div><button class="btn" data-tab="matrix">${icon('compare',true)}Compare currencies</button></div>${S.tab==='matrix'?fxMatrix():S.tab==='note'?researchForm():S.tab==='exposure'?`<div class="split"><section class="panel">${panelTitle('Carry is one part of the return','Unhedged spot, accrual and costs remain separate',evidenceLink('carry'))}<div class="panel-pad"><div class="coverage-grid"><div><strong class="num up">+0.75%</strong><small>Illustrative rate accrual · 3 months</small></div><div><strong class="num down">−1.27%</strong><small>Combined payoff if USD/JPY falls 2%</small></div></div><div class="divider"></div><h2>Net exposure, not listing geography</h2><div class="relationship"><div class="relationship-node"><span class="step">REVENUE</span><h3>Foreign receipts</h3><p>Invoice currency and pricing power.</p></div><span class="relationship-arrow">−</span><div class="relationship-node"><span class="step">OFFSETS</span><h3>Costs & hedges</h3><p>Debt, operating costs and matched hedges.</p></div></div><button class="link-btn" data-evidence="carry">Open the full worked example ${icon('arrow',true)}</button></div></section><aside class="panel panel-pad"><div><h2>What a forward means</h2><p class="small secondary" style="margin-top:15px">A forward rate prices a dated exchange. It is not a forecast of the future spot price.</p><div class="divider"></div><button class="link-btn" data-evidence="forward">Rate, basis & costs ${icon('arrow',true)}</button><button class="link-btn" data-tab="note">Draft an inactive condition ${icon('arrow',true)}</button></div></aside></div>`:`<div class="pair-main">${currencyStrength()}<section class="panel">${panelTitle('Selected pair','Spot price · quote currency per one base unit',ranges())}<div class="quote"><div class="pair-switch"><span>${base} / ${quote}</span><button class="icon-btn" data-action="invert" aria-label="Invert currency pair">${icon('forex')}</button></div><span class="spacer"></span><span class="big num">${spot.toFixed(spot<.1?5:4)}</span><span class="move num ${r>=0?'up':'down'}">${signed(r,2)}% <span class="muted">1M</span></span></div><div class="chart-shell">${chartSvg([{label:`${base}/${quote}`,values:chartData(priceSeries(rawSpot,CURRENCIES.find(c=>c.id===S.asset)?.ret||0,.015,1).map(v=>S.inverted?1/v:v))}],{height:275,labels:lineLabels()})}</div><div class="panel-bottom"><span class="small secondary">${quote} per 1 ${base}</span>${evidenceLink('fx-basis','Quote & source')}</div></section></div><div class="split equal below"><section class="panel panel-pad"><div class="row between"><h2>Pair drivers</h2><span class="tag">Separate evidence</span></div><div class="nudge"><span>Spot trend</span><strong>${r>=0?'Rising':'Falling'}</strong></div><div class="nudge"><span>Two-year gap · ${base} minus ${quote}</span><strong class="num">${signed((S.inverted?-1:1)*({EUR:-140,JPY:-350,GBP:25,CHF:-400,CAD:-175,AUD:-75,NZD:-100}[S.asset]||0),0)} bp</strong></div><div class="nudge"><span>Upcoming rate decision</span><button class="link-btn" data-evidence="fx-events">Inspect calendar ${icon('arrow',true)}</button></div></section><section class="panel panel-pad"><div class="row between"><h2>Carry & exposure</h2>${icon('forex',true)}</div><p class="small secondary" style="margin:16px 0 12px">The interest-rate gap does not equal the return. Add spot, funding and any hedge.</p><button class="link-btn" data-tab="exposure">Inspect the payoff ${icon('arrow',true)}</button><div class="divider"></div><button class="link-btn" data-tab="note">Keep a research condition ${icon('arrow',true)}</button></section></div>`}`;}
function yieldChart(){const plotted=CURVE_NOW.map(v=>v+(S.curveMode==='scenario'?S.shift/100:0));const min=Math.floor((Math.min(...CURVE_OLD,...plotted)-.12)*10)/10,max=Math.ceil((Math.max(...CURVE_OLD,...plotted)+.12)*10)/10;const h=280,W=window.innerWidth<640?340:820,L=24,R=55,T=23,B=34,x=i=>L+i/(TENORS.length-1)*(W-L-R),y=v=>T+(max-v)/(max-min)*(h-T-B);const hypothetical=S.curveMode==='scenario';const now=CURVE_NOW.map(v=>v+(hypothetical?S.shift/100:0));let svg=`<svg class="chart" viewBox="0 0 ${W} ${h}" role="img" aria-label="Illustrative Treasury par-yield curve. ${hypothetical?'Hypothetical parallel shift':'Two-date observed comparison'}">`;Array.from({length:6},(_,i)=>min+(max-min)*i/5).forEach(v=>{svg+=`<line class="gridline" x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}"/><text x="${W-R+13}" y="${y(v)+3}">${v.toFixed(1)}%</text>`;});[[(hypothetical?CURVE_NOW:CURVE_OLD),'var(--compare)',true],[now,'var(--series)',false]].forEach(([v,c,d])=>{svg+=`<path d="${v.map((n,i)=>`${i?'L':'M'}${x(i)},${y(n)}`).join(' ')}" fill="none" stroke="${c}" stroke-width="${d?1.5:2.6}" ${d?'stroke-dasharray="5 5"':''}/>`;if(!d)v.forEach((n,i)=>{svg+=`<circle cx="${x(i)}" cy="${y(n)}" r="${TENORS[i]===S.asset?5:3.5}" stroke="${c}" stroke-width="2" fill="var(--panel)"/>`;});});TENORS.forEach((n,i)=>{if(window.innerWidth<640&&![0,3,4,6,8,9].includes(i))return;svg+=`<text x="${x(i)}" y="${h-9}" text-anchor="${i===0?'start':i>=8?'end':'middle'}">${n}</text>`;});return svg+'</svg>';}
function bonds(){const idx=Math.max(0,TENORS.indexOf(S.asset)),level=CURVE_NOW[idx],change=(CURVE_NOW[idx]-CURVE_OLD[idx])*100,priceImpact=10000*(-5.8*S.shift/10000+.5*42*Math.pow(S.shift/10000,2));const hypothetical=S.curveMode==='scenario';return `${tabs([['overview','Yield curves'],['credit','Credit'],['transmission','Transmission']])}<div class="summary"><div><div class="label">Rates read</div><h2 class="headline">Long yields move higher.</h2><p class="hero-note">Separate yield changes from their implications for each exposure.</p></div><div class="summary-side">${stat('10-year yield','4.25%','Illustrative par curve')}${stat('2s10s slope','+36 bp','10Y minus 2Y')}</div></div>${S.tab==='credit'?`<div class="split"><section class="panel">${panelTitle('Credit is more than the spread','Option-adjusted spreads · basis points',evidenceLink('credit'))}<div class="chart-shell">${chartSvg([{label:'Investment grade OAS',values:curve(121,112,96,.1)},{label:'High yield OAS',values:curve(121,345,318,.06,1)}],{height:280,area:false,unit:'bp'})}</div><div class="panel-bottom"><div class="legend"><span><i class="legend-line"></i>Investment grade</span><span><i class="legend-line compare"></i>High yield</span></div>${evidenceLink('spread')}</div></section><aside class="panel panel-pad"><div><h2>Three different questions</h2><div class="evidence-row"><h3>Credit price</h3><p class="reason">What spread does the market demand?</p></div><div class="evidence-row"><h3>Market functioning</h3><p class="reason">${S.state==='partial'?'Current functioning data is unavailable.':'Can investors transact without unusual friction?'}</p></div><div class="evidence-row"><h3>Borrower capacity</h3><p class="reason">What happens when debt refinances?</p></div><button class="link-btn" data-evidence="refinancing">Refinancing sensitivity ${icon('arrow',true)}</button></div></aside></div>`:S.tab==='transmission'?`<section class="panel">${panelTitle('From rates to an exposure','Competing mechanisms; no automatic risk-on conclusion',evidenceLink('transmission'))}<div class="relationship"><div class="relationship-node"><span class="step">OBSERVED</span><h3>Long yields rise</h3><p>Curve level and change, with matching dates and curve definitions.</p></div><span class="relationship-arrow">→</span><div class="relationship-node"><span class="step">EXPLANATION</span><h3>Growth, inflation, premium</h3><p>Inspect alternative decompositions, with vintage and counterevidence.</p><button class="link-btn" data-evidence="decomposition">Compare mechanisms</button></div><span class="relationship-arrow">→</span><div class="relationship-node"><span class="step">EXPOSURE</span><h3>Cash flow & duration</h3><p>Examine refinancing, currency, horizon and interest-rate sensitivity.</p><button class="link-btn" data-evidence="refinancing">Inspect an exposure</button></div></div></section>`:`<div class="split"><section class="panel">${hypothetical?'<div class="scenario-header">Hypothetical parallel shift · not an observed curve</div>':''}${panelTitle('US Treasury curve','Par yields · two-date comparison',`<div class="seg"><button class="${!hypothetical?'on':''}" data-curve="observed">Compare dates</button><button class="${hypothetical?'on':''}" data-curve="scenario">Scenario</button></div>`)}<div class="asset-pills" style="padding:16px 23px 0;margin:0">${['2Y','5Y','10Y','30Y'].map(t=>`<button data-asset="${t}" class="${S.asset===t?'on':''}">${t}</button>`).join('')}</div><div class="chart-shell">${yieldChart()}</div><div class="panel-bottom"><div class="legend"><span><i class="legend-line"></i>${hypothetical?signed(S.shift,0)+' bp shift':'30 Jun'}</span><span><i class="legend-line compare"></i>${hypothetical?'30 Jun base':'23 Jun'}</span></div>${evidenceLink('curve','Curve definition')}</div><div class="chart-shell drawdown">${barChart(CURVE_NOW.map((v,i)=>(v-CURVE_OLD[i])*100),TENORS,'Observed change · 23–30 Jun · bp',115)}</div></section><aside><section class="panel panel-pad"><div class="row between"><h2>${S.asset} Treasury</h2><span class="pill">Par yield</span></div><div style="margin-top:18px"><span class="readout-number num">${level.toFixed(2)}<span style="font-size:23px">%</span></span><span class="num small ${change>=0?'up':'down'}" style="margin-left:12px">${signed(change,0)} bp</span></div><div class="divider"></div><p class="small secondary">The yield moved higher. The price effect depends on the instrument and horizon.</p><button class="link-btn" data-evidence="yield-return">Yield versus return ${icon('arrow',true)}</button></section><section class="panel panel-pad below"><div class="row between"><h2>Sample exposure</h2><span class="tag">Hypothetical</span></div><div class="curve-measures"><div><small>Position</small><strong class="num">$10k</strong></div><div><small>Mod. duration</small><strong class="num">5.8</strong></div><div><small>Convexity</small><strong class="num">42</strong></div></div><div class="scenario-field" style="margin-top:22px"><label>Parallel yield shift <strong class="num">${signed(S.shift,0)} bp</strong></label><input type="range" min="-100" max="100" step="5" value="${S.shift}" data-slider="shift" aria-label="Hypothetical parallel yield shift"></div><div class="scenario-result"><span class="small secondary">Estimated price change</span><strong class="num ${priceImpact>=0?'up':'down'}" id="bond-sensitivity">${priceImpact>=0?'+':'−'}$${money(Math.abs(priceImpact))}</strong></div><button class="link-btn" data-evidence="duration">Assumptions & limits ${icon('arrow',true)}</button></section></aside></div>`}`;}
const EMPTY_COPY={crypto:['No assets match this view','Clear the selected universe filters to see the market board.'],bitcoin:['No qualified decision in this window','Choose a window with a recorded decision. Price history is a separate source.'],record:['No comparable record in this window','The selected dates do not contain a qualified strategy and benchmark pair.'],commodities:['No markets selected','Choose an instrument or return to the full complex.'],strategies:['No qualified strategy result','No evaluated model meets the selected market and history requirements.'],reserves:['No comparable stock record','A missing release is not a zero stock. Choose another source or vintage.'],forex:['No pair in this selection','Choose a supported base and quote currency to continue.'],bonds:['No matching curve dates','Choose two dates with the same qualified curve definition.']};
function render(push=false){rememberDraft();document.documentElement.dataset.theme=S.theme;document.title=`${meta().name} · Mastermind design study`;document.getElementById('page-directory').innerHTML=PAGES.map(x=>`<button data-go="${x.id}" class="${x.id===S.page?'on':''}" aria-current="${x.id===S.page?'page':'false'}">${x.short}</button>`).join('');document.getElementById('theme-button').innerHTML=icon(S.theme==='dark'?'sun':'moon');document.getElementById('help-button').innerHTML=icon('help');document.getElementById('rail-home').innerHTML=icon('home');document.getElementById('rail-market').innerHTML=icon('market');document.getElementById('rail-search').innerHTML=icon('search');document.getElementById('rail-settings').innerHTML=icon('settings');document.getElementById('state-picker').innerHTML=[['default','Primary'],['partial','Source gap'],['conflict','Conflict'],['empty','Empty'],['loading','Loading'],['error','Error']].map(([id,t])=>`<button data-state="${id}" class="${S.state===id?'on':''}" aria-pressed="${S.state===id}">${t}</button>`).join('');let body=S.state==='loading'?skeleton():S.state==='empty'?`<section class="panel">${emptyState(...EMPTY_COPY[S.page])}</section>`:S.state==='error'?`<section class="panel">${emptyState('This analysis could not be loaded','Navigation and your selected view are preserved. Retry this source without losing your place.','Retry source')}</section>`:({crypto,bitcoin,record,commodities,strategies,reserves,forex,bonds}[S.page]());body=body.includes('class="task-tabs"')?body.replace(/(<div class="task-tabs"[\s\S]*?<\/div>)/,'$1<div id="analysis-content" role="tabpanel" tabindex="0" aria-labelledby="tab-'+S.tab+'">')+'</div>':'<div id="analysis-content">'+body+'</div>';document.getElementById('page').innerHTML=pageHeader()+stateNotice()+body;saveHash(push);bindForm();if(S.evidence)showEvidence(S.evidence,false);else if(document.getElementById('evidence-dialog').open)document.getElementById('evidence-dialog').close();}
const TOPICS={
 'fx-gap':['CHF source delayed','No current cross return is shown when either CHF leg is delayed. Its color is neutral and the observation is withheld. Inspect a different pair or return to the full illustrative dataset.'],
 chart:['Chart source & method','Series must share an explicit calendar and return convention. A rebased series is a comparison of change, not market size. Missing intervals remain gaps.'],
 breadth:['Market participation','The illustrative breadth fixture is 34 of 50 eligible assets above their 50-day trend. Production uses the incumbent universe, eligibility rules, timestamp and numerator/denominator. A six-row featured list is not a new denominator.'],
 universe:['Asset universe','The featured board is a selected slice. Production retains the existing ranked lanes, full universe filters, listed-crypto equity links, source eligibility and insufficient-history records.'],
 model:['Model allocation','45% is an illustrative canonical model target. It is not account exposure. The production consumer displays BitcoinDecisionState without recomputing a second allocation. A valid zero, unavailable decision and unknown sleeve breakdown remain distinct.'],
 replay:['Historical evidence','Replay must bind price, decision, input availability and model version to the same historical record. Observation date is not knowledge time. If point-in-time evidence is incomplete, the replay is withheld while current inspectable data remains available.'],
 returns:['Return comparison','Net model and benchmark returns use matching dates and currency. Changing the selected start rebases both series. The sample paths are generated design fixtures; their values demonstrate chart and comparison behavior only.'],
 costs:['Costs & implementation','Record the exact fees, spread, slippage, financing, roll and rebalancing assumptions attached to this version. A missing cost cannot silently become zero. Changed parameters create a new experiment rather than replacing the original record.'],
 windows:['Return windows','A publisher calendar-month return is different from a rolling 20-session return. Keep window_start, window_end, trading-calendar identity and adjustment convention. Overlapping lookback returns must never be connected as a chronological price line.'],
 roll:['Contract & roll method','Identify spot versus individual futures contract versus continuous series. Keep contract month, delivery point, currency, physical unit, roll dates and adjustment method. A roll artifact must not look like a market shock.'],
 relationships:['Mechanism evidence','The observation, explanation-to-test, evidence and contradiction have separate identities. Company continuations come from the existing identity-qualified transmission adapter. Co-movement alone is not a verified causal mechanism.'],
 physical:['Physical evidence','Stock, production, consumption, shipment and capacity are different measures. Each observation keeps its own units, coverage, release date and revision. Earlier physical context must not inherit the price feed’s freshness.'],
 sensitivity:['Hypothetical sensitivity','This design fixture uses base_return − (cost_bp ÷ 100 × 12 rebalances) + roll_pp. It is a simple additive sensitivity, not a strategy backtest or forecast. Production requires the existing evaluator’s cost, roll and position conventions.'],
 'reserve-scope':['Reserve definition','Keep strategic, commercial and total national stocks separate. An authorized capacity is not the usable volume. Country-level figures are not ranked as like-for-like unless scope, coverage, units and vintages align.'],
 coverage:['Coverage denominator','Days of coverage = the stated stock divided by the selected daily-flow denominator. Net imports and consumption answer different questions. The fixture denominator is illustrative; production must use the country-specific qualified denominator and its date.'],
 revisions:['Release vintages','The first publication and revised publication remain available, linked to the analyses that used them. Announced purchases, contracted deliveries, physical arrivals and published stock changes are separate events.'],
 'reserve-event':['Original versus revised','Illustrative revision: 401.8 million barrels → 402.4 million barrels. The 0.6 million revision is a correction, not a new delivery. The original stock estimate remains inspectable; dependent results name their source vintage.'],
 'fx-basis':['Quote and return convention','EUR/USD means USD per one EUR. Inversion uses p′ = 1/p; the inverted return is 1/(1+r) − 1, not −r. Compare matched timestamps, market-day cutoffs and units. Forward points and carry are separate fields.'],
 'fx-matrix':['Cross-currency comparison','Each cell is the base currency’s change in quote-currency terms. With common reference returns b and q, the cell is (1+b)/(1+q) − 1. Reciprocal pairs and dollar baskets are related observations, not independent confirmation votes.'],
 carry:['Illustrative carry example','JPY-funded USD deposit: USD/JPY 150, USD rate 4.5%, JPY funding 1.5%, simple three-month accrual. Unchanged spot yields +0.75% of initial funding principal. A 2% fall in USD/JPY gives −1.2725%. This is not return on equity or an executable offer.'],
 forward:['Forward, basis and funding','A dated forward exchange depends on the matched rates, basis, conventions and costs. It is not a spot forecast. The idealized no-basis forward in the worked example is 148.8875 JPY per USD; fully covered net pickup is zero under those assumptions.'],
 curve:['Curve definition','This design shows par yields. Par, zero and forward curves cannot silently substitute for one another. Keep tenor, source timestamp, interpolation, day-count convention and curve vintage with the selected comparison.'],
 'yield-return':['Yield is not total return','Yield level is shown in percent; yield change in basis points. Price response, accrued interest, carry, reinvestment, horizon and currency determine other return measures. Do not relabel a yield move as a total return.'],
 duration:['Price sensitivity assumptions','Illustrative option-free position: value $10,000; modified duration 5.8; convexity 42. Estimated price change = V × (−D × Δy + 0.5 × C × Δy²), with Δy in decimal units. At +50 bp the estimate is −$284.75. It excludes income, curve twist, spread moves, optionality and trading costs.'],
 credit:['Three credit questions','Credit price, market functioning and borrower cash-flow capacity are separate questions. Tight spreads do not prove low refinancing risk. A functioning-data gap cannot inherit a healthy state from the spread chart.'],
 refinancing:['Refinancing exposure','Separate maturities, fixed/floating coupons, coverage, currency, hedges and operating-profit assumptions. A sensitivity can reveal pressure without claiming a default probability or changing a validated decision model.'],
 decomposition:['Alternative explanations','Expected rate path plus term premium and real yield plus inflation compensation are alternative decompositions. Do not count them as four independent confirmations. Term premium is estimated; breakeven includes more than a pure inflation forecast.'],
 quality:['Source qualification','An observation can be current, delayed, stale, missing, revised or unsupported. Qualification belongs to the incumbent producer. The UI contains a failure to its affected panel, retains working context and never fabricates a current value.'],
 decision:['Decision record','Open the exact model version, event time, information-available time, source-vintage identifiers and original decision. Later revisions are linked, not substituted into the record that produced the historical action.'],
 conditions:['Condition evidence','Each condition binds a metric, unit, comparison, threshold owner, source vintage, expiry and evaluation status. Draft research does not arm a monitor. An unqualified source makes the affected condition unavailable, not passed.'],
 company:['Company continuation','Use existing identity-qualified company links and preserve the selected commodity, hypothesis, period and return destination. Never guess a company identity from a bare ticker or create a second company analysis owner.'],
 strategy:['Strategy evaluation','Keep the existing model identity, parameter version, sample, benchmark, cost conventions, validation scope and independent observation status. Backtest, simulated and live records are separate evidence classes.'],
 experiment:['Experiment record','New parameters or transformations produce a new experiment identity. Holdouts, point-in-time inputs and existing acceptance remain protected. A visually attractive result does not authorize a trade.'],
 experiments:['Experiment history','Show the original versions and their qualification states. A later winner does not erase the tests that preceded it; rejected, incomplete and incomparable records remain distinguishable.'],
 history:['History and evidence','Preserve the original record and its known-time inputs. The timeline changes the selected context; it must not silently restate the past using today’s corrected data.'],
 driver:['Driver evidence','Select a driver to see its definition, observation window, source coverage, time alignment and contradiction. The visual track reflects an existing output; the UI does not invent a combined confidence score.'],
 'fx-events':['Event context','Events retain the release timezone, expected-versus-actual distinction and available-at timestamp. News and policy context never silently become model allocation authority.'],
 spread:['Spread definition','Option-adjusted spread, nominal spread and asset-swap spread have different conventions. Compare like definitions, currencies and duration exposure. A market aggregate is not a single bond’s available execution quote.'],
 transmission:['Transmission evidence','Start with the observed change, compare mechanisms, then inspect the selected exposure and countercase. A bond rally or steepening is not automatically an equity all-clear.']
};
function openDialog(id){lastFocus=document.activeElement;const d=document.getElementById(id);if(!d.open)d.showModal();}
function closeDialog(d){d.close();if(d.id==='evidence-dialog'){S.evidence='';saveHash(true);}if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});else document.getElementById('main').focus({preventScroll:true});}
function showEvidence(topic='sources',persist=true){S.evidence=topic;if(persist)saveHash(true);const m=meta();let record=null;if(topic.startsWith('decision:')){const d=DECISIONS.find(x=>x.id===topic.split(':')[1]);if(d)record={title:d.title,date:d.date,id:d.id,body:`Model target changed from ${d.before}% to ${d.after}%. ${d.reason}. Recorded drivers: trend ${d.trend.toLowerCase()}, spot demand ${d.spot.toLowerCase()}, leverage ${d.leverage.toLowerCase()}. Version: illustrative-decision-v1. This synthetic record is preserved independently of later replay selections.`};}if(topic.startsWith('reserve-event:')){const [,country,i]=topic.split(':'),d=reserveEventData(country)[Number(i)];if(d&&RESERVES[country])record={title:d[1],date:d[0]+' 2025',id:country+'-EVENT-'+i,body:`${RESERVES[country].name}: ${d[2]}. Amount: ${d[3]}. Record classification: ${d[4]}. Original and revised quantities remain separately identified. Announced quantities do not enter recorded stock. This is a synthetic event fixture.`};}const [title,body]=record?[record.title,record.body]:(Object.hasOwn(TOPICS,topic)?TOPICS[topic]:null)||[`${m.name} sources`,'Inspect the exact selected observation, its definition, availability and source lineage. This is a design fixture; no live source was fetched.'];document.getElementById('evidence-title').textContent=title;document.getElementById('evidence-body').innerHTML=`<div class="notice">Illustrative evidence record. The values and timestamps in this study are not live market data.</div><div class="label">Selected context</div><div class="evidence-kv"><span>Workspace</span><b>${m.name}</b></div><div class="evidence-kv"><span>Selection</span><b>${esc(S.asset)}</b></div><div class="evidence-kv"><span>Window</span><b>${esc(S.range)}</b></div><div class="evidence-kv"><span>Observation</span><b>${record?record.date:S.page==='bitcoin'&&S.replay<100?sampleDate(Math.max(25,Math.round(121*S.replay/100))-1)+' 2025':'30 Jun 2025 · sample'}</b></div><div class="evidence-kv"><span>Availability</span><b>${S.state==='partial'?'One source delayed':S.replay<100?'Historical record only':'Illustrative qualified snapshot'}</b></div>${record?`<div class="evidence-kv"><span>Record</span><b>${record.id}</b></div>`:''}<h3>How to read it</h3><p>${body}</p><h3>What changes with a correction</h3><p>The original vintage remains attached to its record. Corrected data updates the affected analysis and makes the change inspectable.</p><div class="divider"></div><button class="link-btn" data-action="return-context">${icon('arrow',true)}Return to ${m.short}</button>`;openDialog('evidence-dialog');}
function buildGuide(){const m=meta();document.getElementById('build-title').textContent=m.name+' · build guide';document.getElementById('build-body').innerHTML=`<div class="state-notice">${icon('info')}<span><strong>NOT_APPLIED_TO_PAPER.</strong> Interactive design candidate only. Paper, real data integration, protected release and production acceptance remain unproven.</span></div><div class="row between"><span class="label">${m.question}</span><span class="pill">OA${PAGES.indexOf(m)+1} / 8</span></div><h3>Reading order</h3><p>Subject and window → one market interpretation → dominant analytical canvas → concise context → selected evidence. Advanced details and builder requirements stay outside the product glance path.</p><h3>Keep the incumbent</h3><p>${m.preserve}</p><div class="evidence-kv"><span>Current route</span><code>${m.route}</code></div><div class="evidence-kv"><span>Source owner</span><code>${m.owner}</code></div><div class="evidence-kv"><span>Existing contract</span><code>${m.contract}</code></div><h3>Design advancement</h3><p>${m.extend}</p><h3>Capability classification</h3><table><thead><tr><th>Layer</th><th>What this artifact proves</th><th>Next gate</th></tr></thead><tbody><tr><td>Source and reference audit</td><td>Existing route/producer/shell mapping</td><td>Recheck touched source preimages during implementation</td></tr><tr><td>Interactive candidate</td><td>Local selection, views, source drawer, history, themes and key scenarios</td><td>Visual/interaction review</td></tr><tr><td>Paper canvas</td><td>No native effects in this turn</td><td>Serviceable guarded connection and safe exact target</td></tr><tr><td>Production feature</td><td>No live binding or deployment</td><td>Native consumer, focused qualification and real user journey</td></tr></tbody></table><h3>Native integration</h3><p>Implement content-only views under the existing <code>AppShell</code>. Reuse shell identity, entitlement, settings, shared Brain host, navigation and error containment. Adapt incumbent Macro outputs; do not clone quant engines, account stores, alert systems or publication owners. The existing legacy frame is a transition mechanism, not native migration acceptance.</p><h3>Interaction contract</h3><ul><li>Selection, view, period and evidence context survive URL reload and back navigation.</li><li>Evidence is reachable by keyboard and touch. Close restores focus and the selected investigation.</li><li>Loading reserves geometry; empty explains why; source failure preserves the working shell.</li><li>Unknown, zero, stale, partial, revised and conflicting remain distinct. A panel never inherits another source’s clock.</li><li>Mobile recomposes the main question first; tables scroll inside their own region.</li></ul><h3>Required proof before production</h3><p>Qualified source-shaped fixtures, original decision/model identity, point-in-time and units checks, route/anchor compatibility, account transitions, desktop/tablet/mobile, EN/ZH and theme behavior where touched, required CI, protected release and the authenticated production drilldown → evidence → back → reload journey.</p><h3>Fixture scope</h3><p>All price paths, performance, stocks, rates, events and model figures in this artifact are synthetic or explicitly worked examples. The interaction code is a review tool. It is not a data provider, a trading policy, a model backtest or an executable order interface.</p><h3>Full packet</h3><p>See <code>BUILD_GUIDE.md</code>, <code>STATE_AND_ACCEPTANCE_MATRIX.md</code> and the owning plan <code>docs/plans/OTHER_ASSETS_SHARED_SHELL_2026-11-14.md</code>. The full source map names accepted baselines and preserves older Paper identities.</p>`;openDialog('build-dialog');}
function searchResults(){const q=document.getElementById('command-search').value.toLowerCase();const found=PAGES.filter(p=>(p.name+' '+p.short+' '+p.question).toLowerCase().includes(q));document.getElementById('command-results').innerHTML=found.length?found.map(p=>`<button data-go="${p.id}">${icon(p.icon)}<span>${p.name}</span><span class="result-info">${p.question}</span></button>`).join(''):'<p class="muted small" style="padding:20px">No matching workspace. Try “Crypto”, “rates” or “reserves”.</p>';}
function search(){openDialog('command-dialog');document.getElementById('command-search').value='';searchResults();document.getElementById('command-search').focus();}
function toast(message){const e=document.getElementById('toast');e.textContent=message;e.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{e.hidden=true},3500);}
function bindForm(){const f=document.getElementById('research-form');if(f)f.addEventListener('submit',e=>{e.preventDefault();if(!f.reportValidity())return;const note={schema:'mmx.other-assets.design-fixture.inactive-note.v1',status:'INACTIVE_DESIGN_FIXTURE',workspace:S.page,asset:S.asset,explanation:f.querySelector('#thesis').value,metric:f.querySelector('#metric').value,threshold:Number(f.querySelector('#threshold').value),unit:f.querySelector('#unit').value,source_id:f.querySelector('#source').value,window:S.range,source_status:'ILLUSTRATIVE',operator:f.querySelector('#operator').value,countercase:f.querySelector('#note').value,monitoring_started:false};const blob=new Blob([JSON.stringify(note,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Inactive_Research_Note_Design_Fixture.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Inactive design note exported. No monitoring was started.');});}
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-asset]');if(!el)return;if(el.hasAttribute('data-close')){closeDialog(el.closest('dialog'));return;}if(el.dataset.go){document.querySelectorAll('dialog[open]').forEach(d=>d.close());nav(el.dataset.go);return;}if(el.dataset.evidence){showEvidence(el.dataset.evidence);return;}if(el.dataset.state){S.state=el.dataset.state;render(true);return;}if(el.dataset.tab){S.tab=el.dataset.tab;if(el.dataset.asset)S.asset=el.dataset.asset;render(true);return;}if(el.dataset.asset){S.asset=el.dataset.asset;if(S.page==='reserves'&&S.tab==='compare')S.tab='overview';render(true);return;}if(el.dataset.range){S.range=el.dataset.range;render(true);return;}if(el.dataset.curve){S.curveMode=el.dataset.curve;render(true);return;}if(el.dataset.reserveBasis){S.reserveBasis=el.dataset.reserveBasis;render(true);return;}if(el.dataset.compare){const id=el.dataset.compare;if(S.compare.includes(id))S.compare=S.compare.filter(x=>x!==id);else if(S.compare.length<4)S.compare.push(id);else toast('Compare up to four markets. Remove one to add another.');render(true);return;}if(el.dataset.pair){const [b,q]=el.dataset.pair.split('/');if(S.state==='partial'&&(b==='CHF'||q==='CHF')){showEvidence('fx-gap');return;}if(q==='USD'){S.asset=b;S.inverted=false;S.tab='overview';render(true);}else if(b==='USD'){S.asset=q;S.inverted=true;S.tab='overview';render(true);}else{document.getElementById('evidence-title').textContent=b+' / '+q;document.getElementById('evidence-body').innerHTML=`<div class="notice">Illustrative cross-currency observation.</div><div class="label">One-month spot return</div><div class="readout-number num" style="margin:18px 0">${signed(pairReturn(b,q),2)}%</div><p>${q} per 1 ${b}. Same reference window and currency-return basis.</p><div class="divider"></div><p>${TOPICS['fx-matrix'][1]}</p><button class="link-btn" data-action="return-context">Return to the matrix</button>`;openDialog('evidence-dialog');}return;}const action=el.dataset.action;if(!action)return;if(action==='theme'){S.theme=S.theme==='dark'?'light':'dark';render(true);}else if(action==='sources')showEvidence();else if(action==='build')buildGuide();else if(action==='search'||action==='directory')search();else if(action==='reset'){S.state='default';render(true);}else if(action==='latest'){S.replay=100;render(true);}else if(action==='clear-brush'){S.brush=0;S.range='6M';render(true);}else if(action==='invert'){S.inverted=!S.inverted;render(true);}else if(action==='return-context'){closeDialog(document.getElementById('evidence-dialog'));}else if(action==='restore-compare'){S.compare=['gold','wti','copper'];render(true);}else if(action==='all-commodities'){S.tab='overview';render(true);toast('All 17 markets are available in the complex map.');}else if(action==='states'){const states=['default','partial','conflict','empty','loading','error'];S.state=states[(states.indexOf(S.state)+1)%states.length];render(true);toast('Design state: '+S.state);}else if(action==='share'){saveHash();try{await navigator.clipboard.writeText(location.href);toast('View link copied. Selection and source state are included.');}catch{toast('This browser cannot copy automatically. The address bar contains the complete view.');}}});
document.addEventListener('input',e=>{if(e.target.closest('#research-form'))rememberDraft();});
document.addEventListener('change',e=>{if(e.target.dataset.slider){const type=e.target.dataset.slider;S[type]=Number(e.target.value);if(type==='shift')S.curveMode='scenario';render(true);const next=document.querySelector(`[data-slider="${type}"]`);next?.focus({preventScroll:true});}});
document.addEventListener('keydown',e=>{if(e.target.matches('[role=tab]')&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const all=[...document.querySelectorAll('[role=tab]')],i=all.indexOf(e.target),next=e.key==='Home'?0:e.key==='End'?all.length-1:(i+(e.key==='ArrowRight'?1:-1)+all.length)%all.length;const id=all[next].dataset.tab;all[next].click();document.getElementById('tab-'+id)?.focus();return;}if((e.key==='k'&&(e.metaKey||e.ctrlKey))||(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName))){e.preventDefault();search();}if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr[data-asset]')){e.preventDefault();S.asset=e.target.dataset.asset;render(true);}});
document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d);}});d.addEventListener('cancel',e=>{e.preventDefault();closeDialog(d);});});
document.getElementById('command-search').addEventListener('input',searchResults);
window.addEventListener('popstate',()=>{readHash();render();});
window.addEventListener('hashchange',()=>{readHash();render();});
let narrowChart=window.innerWidth<640;window.addEventListener('resize',()=>{const n=window.innerWidth<640;if(n!==narrowChart){narrowChart=n;render();}});
window.OAReview={getState:()=>({...S}),setState:p=>{S={...S,...p};render();},pages:PAGES,decisions:DECISIONS,pairReturn,maxDD,model:MODEL,benchmark:BENCH,commodities:COMMODITIES};
readHash();render();
